# AniList Anime Dataset -> Kaggle (Windmill port)
#
# Self-contained Windmill Python script. Ported from main.py / fetch_data.py /
# upload_data.py. It fetches every anime from the AniList GraphQL API using
# year-based pagination (the workaround for AniList's 5,000-record cap), writes
# CSV / XLSX / pickle into an ephemeral per-run temp dir, and publishes a new
# version of the Kaggle dataset.
#
# Kaggle credentials come from two Windmill SECRET variables (no kaggle.json
# file is mounted). Set their paths via the main() parameters below. The script
# exports them as KAGGLE_USERNAME / KAGGLE_KEY, which the kaggle library reads
# natively.
#
# The original fetch_data.py and kaggle_dataset_description.md are embedded
# below as base64 so the published dataset keeps the exact same file list. To
# regenerate them: base64 -w0 fetch_data.py  and  base64 -w0 description.md
#
# Windmill installs the dependencies in this block with uv. When a requirements
# block is present, Windmill does NOT auto-add the wmill client, so it must be
# listed explicitly (openpyxl is also listed because pandas imports it lazily and
# import-based detection would miss it).
#requirements:
#pandas==2.2.3
#requests==2.32.3
#kaggle==1.7.4.2
#openpyxl==3.1.5
#wmill

import base64
import json
import logging
import os
import shutil
import sys
import tempfile
import time
from pathlib import Path

import pandas as pd
import requests
import wmill

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
    handlers=[logging.StreamHandler(sys.stdout)],
)
logger = logging.getLogger("anilist_to_kaggle")

# AniList GraphQL API endpoint
ANILIST_API = "https://graphql.anilist.co"

# Kaggle dataset metadata, inlined from data/kaggle/kaggle_dataset_metadata.json.
# The markdown description (embedded below) is injected into the "description"
# field at upload time, matching the original upload_data.py behavior.
KAGGLE_METADATA = {
    "title": "AniList Anime Dataset - Complete Collection",
    "subtitle": "Comprehensive dataset of all anime from AniList with detailed attributes",
    "description": "",
    "id": "calebmwelsh/anilist-anime-dataset",
    "licenses": [{"name": "CC0-1.0"}],
    "keywords": [
        "anime",
        "entertainment",
        "media",
        "japanese animation",
        "anilist",
        "recommendation systems",
        "data analysis",
    ],
    "resources": [
        {"path": "anilist_anime_data_complete.csv", "description": "Complete anime dataset in CSV format"},
        {"path": "anilist_anime_data_complete.xlsx", "description": "Complete anime dataset in Excel format"},
        {"path": "anilist_anime_data_complete.pkl", "description": "Complete anime dataset in Python pickle format"},
        {"path": "kaggle_dataset_description.md", "description": "Detailed description of dataset columns and structure"},
        {"path": "fetch_data.py", "description": "Python script to fetch and preprocess the dataset"},
    ],
}

# --- embedded dataset files (base64; see header for how to regenerate) ---
FETCH_DATA_PY_B64 = ""
KAGGLE_DESCRIPTION_B64 = ""

# GraphQL query to fetch anime data with all attributes (identical to the
# original fetch_data.py query).
QUERY = """
query ($page: Int, $perPage: Int, $startDate: FuzzyDateInt, $endDate: FuzzyDateInt) {
  Page(page: $page, perPage: $perPage) {
    pageInfo {
      total
      currentPage
      lastPage
      hasNextPage
      perPage
    }
    media(type: ANIME, startDate_greater: $startDate, startDate_lesser: $endDate) {
      id
      idMal
      title { romaji english native userPreferred }
      type
      format
      status
      description
      startDate { year month day }
      endDate { year month day }
      season
      seasonYear
      seasonInt
      episodes
      duration
      chapters
      volumes
      countryOfOrigin
      isLicensed
      source
      hashtag
      trailer { id site thumbnail }
      updatedAt
      coverImage { extraLarge large medium color }
      bannerImage
      genres
      synonyms
      tags { id name description category rank isGeneralSpoiler isMediaSpoiler isAdult }
      averageScore
      meanScore
      popularity
      favourites
      trending
      rankings { id rank type format year season allTime context }
      isFavourite
      isAdult
      isLocked
      siteUrl
      externalLinks { id url site type language color icon notes isDisabled }
      streamingEpisodes { title thumbnail url site }
      relations {
        edges {
          id
          relationType
          node { id title { romaji english native } type format status }
        }
      }
      characters {
        edges {
          id
          role
          name
          voiceActors { id name { full native } languageV2 image { large medium } }
          node { id name { full native alternative } image { large medium } description }
        }
      }
      staff {
        edges {
          id
          role
          node { id name { full native } languageV2 image { large medium } }
        }
      }
      studios {
        edges { id isMain node { id name isAnimationStudio } }
      }
      nextAiringEpisode { id airingAt timeUntilAiring episode mediaId }
      airingSchedule { nodes { id airingAt timeUntilAiring episode mediaId } }
      recommendations {
        edges { node { id rating mediaRecommendation { id title { romaji english native } } } }
      }
      reviews { edges { node { id summary rating score } } }
      stats {
        scoreDistribution { score amount }
        statusDistribution { status amount }
      }
    }
  }
}
"""

# Year ranges used to batch the full fetch and stay under AniList's 5,000-record
# cap per filter window. Kept identical to the original fetch_data.py.
YEAR_RANGES = [
    (1940, 1965),
    (1966, 1970), (1971, 1975), (1976, 1980),
    (1981, 1985), (1986, 1990), (1991, 1995), (1996, 2000),
    (2001, 2005), (2006, 2007), (2008, 2009),
    (2010, 2011), (2012, 2013), (2014, 2015),
    (2016, 2016), (2017, 2017), (2018, 2018),
    (2019, 2019), (2020, 2020), (2021, 2021),
    (2022, 2022), (2023, 2023), (2024, 2024),
    (2025, 2025),
]


def convert_to_fuzzy_date(year, month=1, day=1):
    """Convert year/month/day to AniList FuzzyDateInt (YYYYMMDD as an int)."""
    return year * 10000 + month * 100 + day


def fetch_anime_page(page, per_page=50, start_year=None, end_year=None):
    """Fetch a single page of anime from the AniList GraphQL API."""
    start_date = convert_to_fuzzy_date(start_year, 1, 1) if start_year else None
    end_date = convert_to_fuzzy_date(end_year, 12, 31) if end_year else None

    payload = {
        "query": QUERY,
        "variables": {
            "page": page,
            "perPage": per_page,
            "startDate": start_date,
            "endDate": end_date,
        },
    }
    headers = {"Content-Type": "application/json", "Accept": "application/json"}

    try:
        response = requests.post(ANILIST_API, json=payload, headers=headers)

        # Handle rate limiting with the server-provided backoff.
        if response.status_code == 429:
            retry_after = int(response.headers.get("Retry-After", 60))
            logger.warning(f"Rate limited. Waiting {retry_after}s...")
            time.sleep(retry_after)
            return fetch_anime_page(page, per_page, start_year, end_year)

        if response.status_code != 200:
            logger.error(f"Error {response.status_code}: {response.text}")
            return None

        return response.json()
    except Exception as e:
        logger.error(f"Error fetching anime page: {e}")
        return None


def flatten_anime_data(anime):
    """Flatten one nested anime record into a flat dict for a DataFrame row."""
    flattened = {}

    flattened["id"] = anime.get("id")
    flattened["idMal"] = anime.get("idMal")

    title = anime.get("title", {})
    flattened["title_romaji"] = title.get("romaji")
    flattened["title_english"] = title.get("english")
    flattened["title_native"] = title.get("native")
    flattened["title_userPreferred"] = title.get("userPreferred")

    flattened["type"] = anime.get("type")
    flattened["format"] = anime.get("format")
    flattened["status"] = anime.get("status")
    flattened["description"] = anime.get("description")

    start_date = anime.get("startDate", {})
    flattened["startDate_year"] = start_date.get("year")
    flattened["startDate_month"] = start_date.get("month")
    flattened["startDate_day"] = start_date.get("day")

    end_date = anime.get("endDate", {})
    flattened["endDate_year"] = end_date.get("year")
    flattened["endDate_month"] = end_date.get("month")
    flattened["endDate_day"] = end_date.get("day")

    flattened["season"] = anime.get("season")
    flattened["seasonYear"] = anime.get("seasonYear")
    flattened["seasonInt"] = anime.get("seasonInt")

    flattened["episodes"] = anime.get("episodes")
    flattened["duration"] = anime.get("duration")
    flattened["chapters"] = anime.get("chapters")
    flattened["volumes"] = anime.get("volumes")

    flattened["countryOfOrigin"] = anime.get("countryOfOrigin")
    flattened["isLicensed"] = anime.get("isLicensed")
    flattened["source"] = anime.get("source")
    flattened["hashtag"] = anime.get("hashtag")

    trailer = anime.get("trailer") or {}
    flattened["trailer_id"] = trailer.get("id")
    flattened["trailer_site"] = trailer.get("site")
    flattened["trailer_thumbnail"] = trailer.get("thumbnail")

    flattened["updatedAt"] = anime.get("updatedAt")

    cover_image = anime.get("coverImage", {})
    flattened["coverImage_extraLarge"] = cover_image.get("extraLarge")
    flattened["coverImage_large"] = cover_image.get("large")
    flattened["coverImage_medium"] = cover_image.get("medium")
    flattened["coverImage_color"] = cover_image.get("color")
    flattened["bannerImage"] = anime.get("bannerImage")

    flattened["genres"] = json.dumps(anime.get("genres", []))
    flattened["synonyms"] = json.dumps(anime.get("synonyms", []))
    flattened["tags"] = json.dumps(anime.get("tags", []))

    flattened["averageScore"] = anime.get("averageScore")
    flattened["meanScore"] = anime.get("meanScore")
    flattened["popularity"] = anime.get("popularity")
    flattened["favourites"] = anime.get("favourites")
    flattened["trending"] = anime.get("trending")

    flattened["rankings"] = json.dumps(anime.get("rankings", []))

    flattened["isFavourite"] = anime.get("isFavourite")
    flattened["isAdult"] = anime.get("isAdult")
    flattened["isLocked"] = anime.get("isLocked")

    flattened["siteUrl"] = anime.get("siteUrl")
    flattened["externalLinks"] = json.dumps(anime.get("externalLinks", []))
    flattened["streamingEpisodes"] = json.dumps(anime.get("streamingEpisodes", []))

    flattened["relations"] = json.dumps(anime.get("relations", {}).get("edges", []))
    flattened["characters"] = json.dumps(anime.get("characters", {}).get("edges", []))
    flattened["staff"] = json.dumps(anime.get("staff", {}).get("edges", []))
    flattened["studios"] = json.dumps(anime.get("studios", {}).get("edges", []))

    next_airing_episode = anime.get("nextAiringEpisode", {})
    flattened["nextAiringEpisode"] = json.dumps(next_airing_episode) if next_airing_episode else None
    flattened["airingSchedule"] = json.dumps(anime.get("airingSchedule", {}).get("nodes", []))

    flattened["recommendations"] = json.dumps(anime.get("recommendations", {}).get("edges", []))
    flattened["reviews"] = json.dumps(anime.get("reviews", {}).get("edges", []))

    stats = anime.get("stats", {})
    flattened["stats_scoreDistribution"] = json.dumps(stats.get("scoreDistribution", []))
    flattened["stats_statusDistribution"] = json.dumps(stats.get("statusDistribution", []))

    return flattened


def fetch_all_anime(test_mode, batch_dir):
    """
    Fetch all anime across the year ranges, writing per-range pickles into
    batch_dir, and return a deduplicated DataFrame of every record.
    """
    if test_mode:
        year_ranges = [(2020, 2020)]
        logger.info("TEST MODE - only fetching anime from 2020")
    else:
        year_ranges = YEAR_RANGES

    batch_dir = Path(batch_dir)
    batch_dir.mkdir(parents=True, exist_ok=True)

    all_anime = []

    for start_year, end_year in year_ranges:
        logger.info(f"Fetching anime from {start_year} to {end_year}...")

        anime_batch = []
        page = 1
        has_next_page = True

        while has_next_page:
            response = fetch_anime_page(page, per_page=50, start_year=start_year, end_year=end_year)

            if not response or "data" not in response:
                logger.error(f"Failed to fetch page {page} for {start_year}-{end_year}")
                break

            page_info = response["data"]["Page"]["pageInfo"]
            media_list = response["data"]["Page"]["media"]

            for anime in media_list:
                anime_batch.append(flatten_anime_data(anime))

            # Periodic progress log (no tqdm/TTY under Windmill).
            if page % 10 == 0:
                logger.info(f"  {start_year}-{end_year}: page {page}, {len(anime_batch)} records so far")

            has_next_page = page_info["hasNextPage"]
            page += 1

            if test_mode and page > 2:
                logger.info("Test mode: stopping after 2 pages")
                break

            time.sleep(0.5)

        if anime_batch:
            batch_df = pd.DataFrame(anime_batch)
            batch_file = batch_dir / f"anime_{start_year}_{end_year}.pkl"
            batch_df.to_pickle(batch_file)
            logger.info(f"Saved {len(anime_batch)} anime to {batch_file}")
            all_anime.extend(anime_batch)

    df = pd.DataFrame(all_anime)
    if not df.empty:
        df = df.drop_duplicates(subset=["id"])
        logger.info(f"After removing duplicates: {len(df)} unique anime entries")

    return df


def stage_files(raw_dir, working_dir, dataset_id):
    """
    Build the kaggle_upload staging dir: copy the data files that exist, write
    the embedded fetch_data.py and description, and write dataset-metadata.json
    with the description injected. Returns the staging Path.
    """
    raw_dir = Path(raw_dir)
    staging = Path(working_dir) / "kaggle_upload"
    staging.mkdir(parents=True, exist_ok=True)

    data_files = [
        "anilist_anime_data_complete.csv",
        "anilist_anime_data_complete.xlsx",
        "anilist_anime_data_complete.pkl",
    ]
    for fname in data_files:
        src = raw_dir / fname
        if src.exists():
            shutil.copy(src, staging / fname)
            logger.info(f"Staged {fname}")
        else:
            logger.warning(f"Skipping missing data file: {fname}")

    # Embedded reference files shipped with the dataset.
    (staging / "fetch_data.py").write_bytes(base64.b64decode(FETCH_DATA_PY_B64))
    description = base64.b64decode(KAGGLE_DESCRIPTION_B64).decode("utf-8")
    (staging / "kaggle_dataset_description.md").write_text(description, encoding="utf-8")

    metadata = json.loads(json.dumps(KAGGLE_METADATA))  # deep copy
    metadata["id"] = dataset_id
    metadata["description"] = description
    # If xlsx could not be produced (e.g. memory), drop it from the manifest so
    # the upload does not reference a missing file.
    if not (staging / "anilist_anime_data_complete.xlsx").exists():
        metadata["resources"] = [
            r for r in metadata["resources"] if r["path"] != "anilist_anime_data_complete.xlsx"
        ]
        logger.warning("xlsx missing - removed from dataset-metadata.json resources")

    (staging / "dataset-metadata.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    return staging


def upload_to_kaggle(staging, dataset_id):
    """Authenticate and publish a new version of the Kaggle dataset."""
    from kaggle.api.kaggle_api_extended import KaggleApi

    api = KaggleApi()
    api.authenticate()

    try:
        api.dataset_list_files(dataset_id)
        dataset_exists = True
        logger.info(f"Found existing dataset: {dataset_id}")
    except Exception as e:
        dataset_exists = False
        logger.info(f"Dataset does not exist or could not be checked: {e}")

    if dataset_exists:
        logger.info(f"Creating new version of {dataset_id}")
        api.dataset_create_version(str(staging), version_notes="Updated dataset", quiet=False)
    else:
        logger.info(f"Creating new dataset {dataset_id}")
        api.dataset_create_new(str(staging), quiet=False)

    logger.info(f"Uploaded: https://www.kaggle.com/datasets/{dataset_id}")
    return dataset_id


def main(
    no_upload: bool = False,
    test_mode: bool = False,
    dataset_id: str = "",
    kaggle_username_var: str = "f/anime/kaggle_username",
    kaggle_key_var: str = "f/anime/kaggle_key",
):
    """
    Windmill entrypoint.

    no_upload:          dry run - fetch and stage files but skip the Kaggle push.
    test_mode:          fetch only 2020 (a couple of pages) for a fast smoke test.
    dataset_id:         override the Kaggle dataset id (e.g. a throwaway dataset
                        for testing). Empty string uses the real id from
                        KAGGLE_METADATA.
    kaggle_username_var: path to the Windmill secret variable holding the Kaggle
                         username (default f/anime/kaggle_username).
    kaggle_key_var:     path to the Windmill secret variable holding the Kaggle
                         API key.
    """
    working_dir = Path(tempfile.mkdtemp(prefix="anilist_"))
    raw_dir = working_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)

    try:
        df = fetch_all_anime(test_mode=test_mode, batch_dir=working_dir / "batches")
        if df.empty:
            raise RuntimeError("Failed to fetch anime data (empty DataFrame)")

        csv_path = raw_dir / "anilist_anime_data_complete.csv"
        df.to_csv(csv_path, index=True)
        logger.info(f"Saved {len(df)} records to {csv_path}")

        # XLSX is best-effort, exactly as in the original fetch_data.py: on a
        # memory error or Excel's 32,767-char-per-cell limit it logs and the run
        # continues on CSV + pickle.
        try:
            xlsx_path = raw_dir / "anilist_anime_data_complete.xlsx"
            df.to_excel(xlsx_path, index=True)
            logger.info(f"Saved {len(df)} records to {xlsx_path}")
        except Exception as e:
            logger.error(f"Warning: could not save XLSX: {e}")

        pkl_path = raw_dir / "anilist_anime_data_complete.pkl"
        df.to_pickle(pkl_path)
        logger.info(f"Saved {len(df)} records to {pkl_path}")

        effective_id = dataset_id or KAGGLE_METADATA["id"]
        staging = stage_files(raw_dir, working_dir, effective_id)
        staged = sorted(p.name for p in staging.iterdir())

        result = {
            "records": int(len(df)),
            "dataset_id": effective_id,
            "staged_files": staged,
            "uploaded": False,
        }

        if no_upload:
            sizes = {p.name: p.stat().st_size for p in staging.iterdir()}
            logger.info(f"DRY RUN - skipping Kaggle upload. Staged files: {sizes}")
            return result

        # Inject Kaggle credentials from Windmill secret variables into the env
        # the kaggle library reads. No kaggle.json file is written.
        os.environ["KAGGLE_USERNAME"] = wmill.get_variable(kaggle_username_var)
        os.environ["KAGGLE_KEY"] = wmill.get_variable(kaggle_key_var)

        upload_to_kaggle(staging, effective_id)
        result["uploaded"] = True
        return result
    finally:
        shutil.rmtree(working_dir, ignore_errors=True)
